import{c as s,$ as i,Q as r,j as o,g as e,o as n,n as l,m as c}from"./chunks/framework.Ce_49mA8.js";const v=JSON.parse('{"title":"Property & Resources","description":"Practical guide to tracking personal real estate, vehicles, workshop machinery, and warehouse raw material stockpiles in OmniCraft ERP.","frontmatter":{"title":"Property & Resources","description":"Practical guide to tracking personal real estate, vehicles, workshop machinery, and warehouse raw material stockpiles in OmniCraft ERP.","datePublished":"2026-10-28","dateModified":"2026-11-15","order":17},"headers":[],"relativePath":"docs/spaces/moy-kapital/property.md","filePath":"docs/spaces/moy-kapital/property.md","lastUpdated":1794700800000}'),d={name:"docs/spaces/moy-kapital/property.md"},p={id:"property-resources-unified-tangible-asset-registry",tabindex:"-1"};function u(h,t,g,m,y,f){const a=i("DocIcon");return r(),o("div",null,[e("h1",p,[n(a,{name:"capital"}),t[0]||(t[0]=l(" Property & Resources: Unified Tangible Asset Registry ",-1)),t[1]||(t[1]=e("a",{class:"header-anchor",href:"#property-resources-unified-tangible-asset-registry","aria-label":'Permalink to "Property & Resources: Unified Tangible Asset Registry"'},"​",-1))]),t[2]||(t[2]=c('<p>The <strong>Property &amp; Resources</strong> tab consolidates all tangible physical assets owned by the craftsman into a single, unified material registry. Unlike operational cash on bank accounts or exchange-traded securities, this section tracks long-term tangible assets: residential and commercial real estate, storage facilities, workshop studio spaces, commercial utility vehicles, heavy machinery, cutting and sewing systems, precision hand tools, and strategic warehouse stocks of raw materials.</p><p>Tangible assets form the physical bedrock of any craft enterprise. A craftsman&#39;s true capitalization is determined not merely by liquid funds in checking accounts, but by the combined fair market valuation of their production equipment and personal holdings that safeguard workshop stability.</p><hr><h2 id="tangible-funds-architecture" tabindex="-1">Tangible Funds Architecture <a class="header-anchor" href="#tangible-funds-architecture" aria-label="Permalink to &quot;Tangible Funds Architecture&quot;">​</a></h2><p>Physical assets in OmniCraft ERP are categorized into four foundational asset classes:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"></span><div><strong>Real Estate &amp; Land:</strong><br> Workshops, storage facilities, commercial and residential properties, and development plots. </div></li><li><span class="craft-list-bullet"></span><div><strong>Vehicles:</strong><br> Commercial transport vans, logistics trailers, and personal vehicles used for business. </div></li><li><span class="craft-list-bullet"></span><div><strong>Equipment &amp; Machinery:</strong><br> Industrial sewing machines, CNC lasers, precision cutters, workbenches, and specialized tooling. </div></li><li><span class="craft-list-bullet"></span><div><strong>Materials &amp; Inventory:</strong><br> Warehouse stocks of raw materials, metal hardware, packaging supplies, and craft chemicals. </div></li></ul><p>This consolidation bridges the gap between workshop operations and the master balance sheet: the software links production and service facility assets directly to the owner&#39;s personal net worth, preventing loss of oversight over high-value machinery and accumulated inventory.</p><hr><h2 id="summary-kpi-metrics-registry-filtering" tabindex="-1">Summary KPI Metrics &amp; Registry Filtering <a class="header-anchor" href="#summary-kpi-metrics-registry-filtering" aria-label="Permalink to &quot;Summary KPI Metrics &amp; Registry Filtering&quot;">​</a></h2><p>The top section of the screen displays key metrics reflecting your tangible asset position:</p><table class="craft-matrix-table"><thead><tr><th style="width:28%;">All Property</th><th style="width:24%;">Real Estate / Vehicles</th><th style="width:24%;">Equipment</th><th style="width:24%;">Inventory</th></tr></thead><tbody><tr><td><strong>$125,000.00</strong></td><td>$85,000.00</td><td>$25,000.00</td><td>$15,000.00</td></tr></tbody></table><ul><li><strong>&quot;All Property &amp; Materials&quot;:</strong> total fair valuation of all physical resources, weighted strictly by the craftsman&#39;s personal equity share;</li><li><strong>&quot;Real Estate &amp; Vehicles&quot;:</strong> estimated market value of workshop premises, storage spaces, garages, and transportation fleets;</li><li><strong>&quot;Equipment &amp; Machinery&quot;:</strong> book value of fixed assets, heavy machines, laser cutters, and professional shop tooling;</li><li><strong>&quot;Materials &amp; Inventory&quot;:</strong> aggregate cost of current raw material balances (leather, timber, metal, fittings) across all active workspaces.</li></ul><h3 id="category-segment-filter" tabindex="-1">Category Segment Filter <a class="header-anchor" href="#category-segment-filter" aria-label="Permalink to &quot;Category Segment Filter&quot;">​</a></h3><p>Directly beneath the KPI cards, a four-segment filter switch allows instant registry filtering:</p><ul><li><strong>&quot;All Positions&quot;:</strong> complete uninterrupted view of all physical assets;</li><li><strong>&quot;Real Estate &amp; Vehicles&quot;:</strong> filtered listing of land, buildings, and transport;</li><li><strong>&quot;Equipment &amp; Fixed Assets&quot;:</strong> dedicated inventory of machinery and tools;</li><li><strong>&quot;Materials &amp; Inventory&quot;:</strong> warehouse stockpiles with itemized valuations.</li></ul><div class="tip custom-block"><p class="custom-block-title">Separating Liquidity from Tangible Capital</p><p>Never confuse working capital in checking accounts with the value of workshop machinery. A leather splitter or CNC laser cannot be instantaneously liquidated to purchase a batch of hides or settle rent without halting workshop production. Maintaining clean segregation between liquid accounts and tangible property prevents the illusion of excess cash.</p></div><hr><h2 id="three-way-ownership-share-model" tabindex="-1">Three-Way Ownership Share Model <a class="header-anchor" href="#three-way-ownership-share-model" aria-label="Permalink to &quot;Three-Way Ownership Share Model&quot;">​</a></h2><p>The core architectural breakthrough of the Property &amp; Resources module is native support for shared ownership and multi-workspace allocation across personal life and business lines.</p><p>A single physical asset often serves the craftsman&#39;s family, assists in batch production, and supports on-site service calls. For every item, you configure a precise allocation ratio:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Personal Use] + [Production Workspace] + [Service Center] = 100.00%</span></span></code></pre></div><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Tangible Capital</span><div class="formula-heading">Calculating Asset Contribution to Net Worth</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Net Worth Contribution ($)</span><span class="math-op">=</span><span class="math-var">Current Valuation</span><span class="math-op">×</span><span class="math-frac"><span class="math-num">Owner&#39;s Equity Share (%)</span><span class="math-denom">100%</span></span></div></div><div class="formula-card-bottom"><p>When equipment or workspace premises are acquired jointly with business partners, OmniCraft ERP factors consolidated Net Worth strictly proportional to your personal equity percentage. Depreciation expenses are proportionally distributed across workshops according to assigned utilization quotas.</p></div></div><h3 id="hamilton-largest-remainder-balancing" tabindex="-1">Hamilton Largest Remainder Balancing <a class="header-anchor" href="#hamilton-largest-remainder-balancing" aria-label="Permalink to &quot;Hamilton Largest Remainder Balancing&quot;">​</a></h3><p>The ownership share editor incorporates the Hamilton largest remainder algorithm. When you modify the share percentage for one sector, the system automatically recalculates the remaining values, ensuring the total stays locked at 100.00% (10,000 basis points) without rounding drift.</p><p><strong>Workshop Practical Case:</strong></p><p>A craftsman purchases a heavy-duty commercial utility van for $45,000:</p><ol><li><strong>Personal Use (40%):</strong> family travel, personal commutes, and domestic errands;</li><li><strong>Production Workspace (40%):</strong> hauling wholesale hides and timber from suppliers and delivering wholesale product batches;</li><li><strong>Service Center (20%):</strong> mobile diagnostic trips, on-site installations, and customer maintenance visits.</li></ol><p>The owner&#39;s consolidated balance sheet captures the vehicle according to personal ownership equity, while recurring maintenance and depreciation charges are automatically expensed across production and service operations based on these established quotas.</p><hr><h2 id="adding-assets-card-parameters" tabindex="-1">Adding Assets &amp; Card Parameters <a class="header-anchor" href="#adding-assets-card-parameters" aria-label="Permalink to &quot;Adding Assets &amp; Card Parameters&quot;">​</a></h2><p>To log a new physical asset, click <strong>&quot;Add Personal Asset&quot;</strong>. The modal window prompts for standard valuation parameters:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Input Field</th><th style="text-align:left;">Purpose &amp; Formatting</th><th style="text-align:left;">Example Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>&quot;Asset Name&quot;</strong></td><td style="text-align:left;">Identifying title or equipment model</td><td style="text-align:left;"><em>Fortuna SAS Skiving Machine</em>, <em>Ford Transit Custom</em></td></tr><tr><td style="text-align:left;"><strong>&quot;Asset Kind&quot;</strong></td><td style="text-align:left;">Allocation domain (Personal Property / Investments)</td><td style="text-align:left;"><em>Personal Property</em></td></tr><tr><td style="text-align:left;"><strong>&quot;Asset Category&quot;</strong></td><td style="text-align:left;">Operational classification for filtering</td><td style="text-align:left;"><em>Real Estate / Land</em>, <em>Vehicles</em>, <em>Other Valuables</em></td></tr><tr><td style="text-align:left;"><strong>&quot;Purchase Date&quot;</strong></td><td style="text-align:left;">Acquisition or commissioning date</td><td style="text-align:left;"><em>2026-03-15</em> (calendar picker)</td></tr><tr><td style="text-align:left;"><strong>&quot;Purchase Cost&quot;</strong></td><td style="text-align:left;">Historical out-of-pocket acquisition and setup expense</td><td style="text-align:left;"><em>$4,500.00</em></td></tr><tr><td style="text-align:left;"><strong>&quot;Current Estimated Value&quot;</strong></td><td style="text-align:left;">Realistic fair liquidation market value</td><td style="text-align:left;"><em>$3,800.00</em></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Conservative Liquidation Valuation</p><p>For industrial machinery and vehicles, consistently record a conservative liquidation figure—the cash amount you could realistically realize within two to three weeks under urgent liquidity requirements. Inflating valuations breeds false security and skews managerial reporting.</p></div><hr><h2 id="security-collision-audit-fund-normalization" tabindex="-1">Security Collision Audit &amp; Fund Normalization <a class="header-anchor" href="#security-collision-audit-fund-normalization" aria-label="Permalink to &quot;Security Collision Audit &amp; Fund Normalization&quot;">​</a></h2><p>When a craftsman logs tools inside the production workshop while simultaneously tracking personal property, duplicate entries can easily occur: a CNC laser could mistakenly exist both as a workshop fixed asset and as personal property.</p><p>To maintain accounting purity, click <strong>&quot;🛡️ Check Duplicates &amp; Collisions&quot;</strong>:</p><ol><li><strong>Ownership Share Collisions:</strong> scans all assets for allocation totals diverging from 100.00%. The <strong>&quot;Fix Shares (100%)&quot;</strong> action normalizes proportions automatically;</li><li><strong>Potential Duplicate Equipment:</strong> compares personal asset titles against the Workshop / Assets registry. Clicking <strong>&quot;Merge Duplicates&quot;</strong> consolidates redundant cards into a single master record with unified share settings;</li><li><strong>Potential Duplicate Raw Materials:</strong> identifies overlapping entries between personal inventory holdings and operational warehouse stock.</li></ol><div class="tip custom-block"><p class="custom-block-title">Regular Audit Cadence</p><p>Run the collision audit following major equipment acquisitions, workshop reorganizations, or during annual physical inventory counts. This guarantees that balance sheet equity reflects authentic physical assets without phantom duplicates.</p></div><hr><h2 id="smart-delete-guard-retirement-standards" tabindex="-1">Smart Delete Guard &amp; Retirement Standards <a class="header-anchor" href="#smart-delete-guard-retirement-standards" aria-label="Permalink to &quot;Smart Delete Guard &amp; Retirement Standards&quot;">​</a></h2><p>Physical assets are deeply integrated with workshop operations: machinery feeds hourly rate calculations in recipe engineering, while raw materials are expensed during workbench production batches.</p><p>OmniCraft ERP enforces strict structural integrity safeguards:</p><ul><li><strong>Two-Stage Smart Delete Guard:</strong> the software prohibits hard deletion of any asset actively referenced in recipe costings, pending work orders, or warehouse transactions;</li><li><strong>Standard Retirement &amp; Archiving:</strong> when machinery is sold or decommissioned, click <strong>&quot;Delete / Retire&quot;</strong> to archive the record. Historical production costs and job logs remain intact, while current tangible asset equity is reduced accordingly;</li><li><strong>Seamless Proceeds Routing:</strong> upon asset sale, liquidation proceeds can be routed directly to an active account in the <strong>&quot;Accounts &amp; Wallets&quot;</strong> tab, keeping capital cashflows unbroken.</li></ul><div class="warning custom-block"><p class="custom-block-title">Preserving Historical Analytics</p><p>Never attempt to erase or force-delete retired equipment cards. Archiving maintains audit trails for tax compliance and historical managerial accounting, preserving retroactive reporting integrity.</p></div>',45))])}const w=s(d,[["render",u]]);export{v as __pageData,w as default};
